for v,(P,vals) in enumerate([(s.Matrix([[1,1],[1,2]]),[-1,3]),(s.Matrix([[1,2],[1,1]]),[2,5])],1):
 A=P*s.diag(*vals)*P.inv()
 add('reconstruct','R',1,v,'Reconstruct all matrix entries',r'<p>The columns of \(P='+T(P)+r'\) are eigenvectors of A with respective eigenvalues \('+','.join(map(str,vals))+r'\). Find every entry of A.</p>',matrix_fields(A),'<p>Check det P≠0, put the corresponding values in D, then compute PDP⁻¹ in that order.</p>',dict(kind='reconstruct',P=P.tolist(),values=vals))
for v,(M,P) in enumerate([(s.Matrix([[1,2],[0,1]]),s.Matrix([[1,2],[1,1]])),(s.Matrix([[2,1],[1,1]]),s.Matrix([[1,1],[0,1]]))],1):
 result=M*P
 add('reconstruct','R',2,v,'Transport the complete ordered vector matrix',r'<p>A has ordered eigenvector columns \(P='+T(P)+r'\). Let \(B=MAM^{-1}\), where \(M='+T(M)+r'\). Give every entry of the corresponding eigenvector matrix MP for B, preserving exactly these transported vectors.</p>',matrix_fields(result),'<p>For each column v, B(Mv)=MAv=λMv. Multiply M by P, preserving order and the specified scaling.</p>',dict(kind='transport',M=M.tolist(),P=P.tolist()))
for v,(P,vals) in enumerate([(s.Matrix([[1,1],[0,1]]),[-2,3]),(s.Matrix([[1,0],[2,1]]),[2,5])],1):
 A=P*s.diag(*vals)*P.inv()
 add('reconstruct','R',3,v,'Reconstruct the complete inverse',r'<p>The eigenvectors are the columns of \(P='+T(P)+r'\), with respective eigenvalues \('+','.join(map(str,vals))+r'\). Find every entry of A⁻¹.</p>',matrix_fields(A.inv()),'<p>All eigenvalues are non-zero. Reconstruct with P, the reciprocal diagonal entries, and P⁻¹.</p>',dict(kind='reconstruct_inverse',P=P.tolist(),values=vals))
for v,point in enumerate([[1,2,-1],[2,-1,3]],1):
 A=s.Matrix([[1,1,1],[1,2,3],[2,1,1]]);b=A*s.Matrix(point)
 add('systems','S',1,v,'The whole unique solution',r'<p>Solve \('+T(A)+r'\begin{pmatrix}x\\y\\z\end{pmatrix}='+T(b)+r'\). Give all three coordinates.</p>',[f(k,k.upper()+' coordinate',val) for k,val in zip(['x','y','z'],point)],'<p>Eliminate consistently in all equations or use the inverse. Substitute all three coordinates into every original equation.</p>',dict(kind='unique_system',A=A.tolist(),b=list(b)))
for v,(r1,r2) in enumerate([(4,7),(2,5)],1):
 A=s.Matrix([[1,1,1],[1,2,3],[2,3,4]]);sol=[2*r1-r2+t,r2-r1-2*t,t]
 add('systems','S',2,v,'Consistency and the complete common line',r'<p>Solve \(x+y+z='+str(r1)+r'\), \(x+2y+3z='+str(r2)+r'\), \(2x+3y+4z=b\). Give the necessary and sufficient b-value, then the full x(t), y(t), z(t) with z=t for every real t.</p>',[f('b','Consistent right-hand side',r1+r2)]+[f(k,k.upper()+' as a polynomial in t',value,'polynomial',['t']) for k,value in zip(['x','y','z'],sol)],'<p>The third left-hand side is the sum of the first two, so b must equal their right-hand-side sum. Set z=t and solve the remaining two equations.</p>',dict(kind='line_system',rhs=[r1,r2]))
